SELECT r_name
FROM region
ORDER BY r_name ASC;

SELECT n.n_name AS nation_name, r.r_name AS region_name
FROM nation AS n
JOIN region AS r ON n.n_regionkey = r.r_regionkey;

SELECT s_suppkey, s_name, s_address, s_phone, s_acctbal, s_comment
FROM supplier
WHERE CAST(s_acctbal AS REAL) > 0;

SELECT DISTINCT s.s_suppkey, s.s_name
FROM supplier AS s
WHERE s.s_comment LIKE '%customer complaints%';

SELECT * 
FROM part 
WHERE p_mfgr = 'Manufacturer#1';

SELECT p_mfgr, COUNT(*) AS part_count
FROM part
GROUP BY p_mfgr;

SELECT p_partkey, p_name, p_size, p_mfgr, p_brand, p_type, p_container, p_retailprice, p_comment
FROM part
WHERE p_size BETWEEN 10 AND 20;

SELECT p_type, COUNT(*) AS part_count
FROM part
GROUP BY p_type;

SELECT *
FROM part
WHERE p_name LIKE '%green%';

SELECT c_custkey, c_name, c_address, c_phone, c_acctbal, c_comment
FROM customer
WHERE c_mktsegment = 'BUILDING';

SELECT c_custkey, c_name, c_acctbal
FROM customer
WHERE c_has_debt = 1;

SELECT c.c_name, n.n_name
FROM customer AS c
JOIN nation AS n ON c.c_nationkey = n.n_nationkey;

SELECT *
FROM orders
WHERE o_year = 1995;

SELECT o_orderkey, o_custkey, o_totalprice, o_orderdate
FROM orders
WHERE CAST(o_totalprice AS REAL) > 100000;

SELECT o_clerk, COUNT(*) AS order_count
FROM orders
GROUP BY o_clerk;

SELECT *
FROM lineitem AS l
WHERE l.l_shipdate > l.l_commitdate;
